import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BM5YPQmL.js";const b=JSON.parse('{"title":"OCSE：安装失败与恢复","description":"","frontmatter":{},"headers":[],"relativePath":"zh/components/ocse/ocse-recovery.md","filePath":"zh/components/ocse/ocse-recovery.md"}'),s={name:"zh/components/ocse/ocse-recovery.md"};function c(d,e,l,r,i,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="ocse-安装失败与恢复" tabindex="-1">OCSE：安装失败与恢复 <a class="header-anchor" href="#ocse-安装失败与恢复" aria-label="Permalink to &quot;OCSE：安装失败与恢复&quot;">​</a></h1><p>安装出问题时会发生什么，以及为什么中断的安装不会留下一个写了一半 的系统。</p><h2 id="错误页" tabindex="-1">错误页 <a class="header-anchor" href="#错误页" aria-label="Permalink to &quot;错误页&quot;">​</a></h2><p>向导运行的每条 OCSECL 命令都返回状态。首条失败的命令使向导停止： 错误页显示</p><ul><li>失败的<strong>命令行</strong>（逐字复制），以及</li><li>该命令<strong>捕获的输出</strong>（与 shell 会打印的文本相同），</li></ul><p>外加 <strong>Retry</strong> 与 <strong>Back</strong>。Retry 重新运行失败阶段；Back 返回 前一页。错误页驻留期间机器上的其他内容不受影响。</p><h2 id="失败模式与处置" tabindex="-1">失败模式与处置 <a class="header-anchor" href="#失败模式与处置" aria-label="Permalink to &quot;失败模式与处置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>失败</th><th>处置</th></tr></thead><tbody><tr><td>第 2 步</td><td>目标盘已能启动 <code>opencube.elf</code></td><td>任何写入之前即拒绝——既有系统原封不动</td></tr><tr><td>第 3 步</td><td>没有足够大的空闲间隙</td><td>向导如实说明；不写入任何内容</td></tr><tr><td>阶段 1</td><td>此前失败重试残留的挂载导致 <code>mount</code> 失败</td><td>向导丢弃残留挂载（<code>umount /mnt</code>）后<strong>重试一次</strong>挂载，再失败才放弃</td></tr><tr><td>阶段 2</td><td><code>install</code> 内部的介质检查、恢复分区划分、解包、引导代码或引导标志失败</td><td>子步骤自己的 FATAL 文本指明失败点（<code>extraction failed</code> / <code>/boot/opencube.elf missing after extraction</code> / <code>ocbl-install failed</code> / <code>could not set the boot flag</code>）；引导代码只在解包完全成功（已验证 <code>/boot/opencube.elf</code> 存在）之后才写入</td></tr><tr><td>阶段 3/4</td><td>配置值或用户记录装不下</td><td>明确报错拒绝（有界构建器——绝不截断、绝不溢出）</td></tr><tr><td>阶段 5/6</td><td><code>sync</code>/<code>umount</code> 失败</td><td>经错误页重试；已安装的文件已在盘上，之后从 OCSECL 手动 <code>sync</code> 即可收尾</td></tr></tbody></table><h2 id="用-ocsecl-手工恢复" tabindex="-1">用 OCSECL 手工恢复 <a class="header-anchor" href="#用-ocsecl-手工恢复" aria-label="Permalink to &quot;用 OCSECL 手工恢复&quot;">​</a></h2><p>因为向导只是 OCSECL 之上的控制器，失败的安装可以从 shell 检查 并手工完成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lsdisk                       选定目标</span></span>
<span class="line"><span>lspart hd0                   向导创建了什么？</span></span>
<span class="line"><span>mount hd0p2 /mnt             挂载已安装分区</span></span>
<span class="line"><span>ls /mnt                      检查写入了什么</span></span>
<span class="line"><span>cat /mnt/etc/opencube.conf   已写入的配置键</span></span>
<span class="line"><span>config set hostname mybox    补齐缺失的键</span></span>
<span class="line"><span>sync                         刷盘</span></span>
<span class="line"><span>umount /mnt                  完成——重启</span></span></code></pre></div><p><code>hwcheck</code> 随时重新运行四项硬件检查——磁盘行为异常时的第一 选择。</p><h2 id="目标已有系统时" tabindex="-1">目标已有系统时 <a class="header-anchor" href="#目标已有系统时" aria-label="Permalink to &quot;目标已有系统时&quot;">​</a></h2><p>既有系统拒绝是外层守卫：OCSE 绝不格式化、重分区或安装到已能启动 <code>opencube.elf</code> 的分区上。要有意重装旧的 Open Cube OS，请先删除旧 分区（<code>rmpart &lt;disk&gt; &lt;n&gt; confirm</code>）或另选目标——两者都是显式的、 需确认的动作。</p><h2 id="install-的写入顺序" tabindex="-1"><code>install</code> 的写入顺序 <a class="header-anchor" href="#install-的写入顺序" aria-label="Permalink to &quot;\`install\` 的写入顺序&quot;">​</a></h2><p>阶段 2 内部，<code>install</code> 命令按固定顺序执行，首个 FATAL 即中止： 可选的专用 OCIRE 恢复分区划分（布局需要时，系统卷上保留 <code>boot/ocire.elf</code>）、载荷 tar 解包（以 <code>/boot/opencube.elf</code> 存在为 验证）、OCBL 引导代码（<code>ocbl-install</code>——镜像有效性、首分区前的 空间、stage1 + core 校验），最后是所建分区的引导标志。</p><h2 id="安装成功之后" tabindex="-1">安装成功之后 <a class="header-anchor" href="#安装成功之后" aria-label="Permalink to &quot;安装成功之后&quot;">​</a></h2><p>末页提供<strong>重启</strong>。装好的磁盘包含：OCOS 载荷、OCBL 引导代码 （<code>ocbl-install</code> 已在 <code>install</code> 内运行）、所建分区的引导标志、 配置键与用户记录。A/B 恢复盘布局的恢复盘另行准备（见 OCBL 页面）——OCSE 的 <code>install</code> 面向普通单系统布局。</p><p>另见：<a href="./../ocbl/ocbl-troubleshooting.html">OCBL 故障排查与状态码</a>—— 已安装系统头几次启动时引导加载器会报告什么。</p>`,19)])])}const u=t(s,[["render",c]]);export{b as __pageData,u as default};
